import type { listAudit } from "@/lib/admin/queries";
import { dateLabel } from "./common";
export function AuditTable({
  events,
}: {
  events: Awaited<ReturnType<typeof listAudit>>["events"];
}) {
  return (
    <div className="overflow-x-auto">
      <table className="w-full text-left text-sm">
        <caption className="sr-only">Immutable operator audit history</caption>
        <thead>
          <tr>
            {[
              "Time (UTC)",
              "Action / reason",
              "Actor UUID",
              "Target UUID",
              "Change / request UUID",
            ].map((s) => (
              <th
                key={s}
                scope="col"
                className="border-b border-dotted border-separator p-3"
              >
                {s}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {events.map((e) => (
            <tr
              key={e.id}
              className="border-b border-dotted border-separator align-top"
            >
              <td className="p-3">{dateLabel(e.createdAt)}</td>
              <td className="p-3">
                {e.action}
                <div>{e.reason}</div>
              </td>
              <td className="p-3 break-all">{e.actorIdSnapshot ?? "Legacy"}</td>
              <td className="p-3 break-all">
                {e.targetIdSnapshot ?? "Global / legacy"}
              </td>
              <td className="max-w-md p-3 break-all">
                <div>Before: {JSON.stringify(e.before)}</div>
                <div>After: {JSON.stringify(e.after)}</div>
                <div className="mt-2 text-body">{e.requestId ?? "Legacy"}</div>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      {!events.length && (
        <p className="py-6">No audit events match these filters.</p>
      )}
    </div>
  );
}
